import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
import org.vaadin.addons.dramafinder.element.ButtonElement;
import org.vaadin.addons.dramafinder.element.EmailFieldElement;
import org.vaadin.addons.dramafinder.element.NotificationElement;
import org.vaadin.addons.dramafinder.element.TextAreaElement;
import org.vaadin.addons.dramafinder.element.TextFieldElement;

/**
 * Same expectations as {@link ContactViewTest}, but driven through a real
 * browser. Not run by the default surefire includes; run it with
 * {@code mvn -o test -Dtest=ContactViewBrowserIT -DfailIfNoSpecifiedTests=false}.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class ContactViewBrowserIT extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Override
    public String getUrl() {
        return "http://localhost:" + port;
    }

    @Override
    public String getView() {
        return "/contact";
    }

    @Test
    void view_showsFormWithEmptyFields() {
        assertEquals("Contact", page.locator("h1").textContent());
        assertEquals("", name().getValue());
        assertEquals("", email().getValue());
        assertEquals("", message().getValue());
        assertTrue(sendButton().isEnabled(), "Send button should be enabled");
    }

    @Test
    void blankName_doesNotSend() {
        sendButton().click();

        name().assertInvalid();
        assertEquals(0, page.locator("vaadin-notification-card").count(),
                "No notification should be shown");
    }

    @Test
    void filledName_sendsAndClearsFields() {
        name().setValue("Ada");
        email().setValue("ada@example.com");
        message().setValue("Hello there");

        sendButton().click();

        NotificationElement.getByText(page, "Message sent").assertOpen();
        name().assertValue("");
        email().assertValue("");
        message().assertValue("");
        name().assertValid();
    }

    private TextFieldElement name() {
        return TextFieldElement.getByLabel(page, "Name");
    }

    private EmailFieldElement email() {
        return EmailFieldElement.getByLabel(page, "Email");
    }

    private TextAreaElement message() {
        return TextAreaElement.getByLabel(page, "Message");
    }

    private ButtonElement sendButton() {
        return ButtonElement.getByText(page, "Send");
    }
}
