/**
 * The route is exercised from an unrelated package, the way an external test
 * suite that knows nothing but the route name would do it.
 */
@SpringBootTest
class ContactRouteSmokeTest extends SpringBrowserlessTest {

    @Test
    void contactRoute_isReachableAndWorks() {
        navigate("contact", Component.class);

        assertEquals("Contact", $(H1.class).first().getText());
        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();
        Button send = $(Button.class).withText("Send").single();

        test(send).click();
        assertTrue(name.isInvalid());
        assertEquals(0, $(Notification.class).all().size());

        test(name).setValue("Ada");
        test(message).setValue("Hello");
        test(send).click();

        assertTrue(test($(Notification.class).first()).getText().contains("Message sent"));
        assertEquals("", name.getValue());
        assertEquals("", email.getValue());
        assertEquals("", message.getValue());
    }
}
