@SpringBootTest
class ScratchNotificationTest extends SpringBrowserlessTest {

    @Test
    void probe() {
        navigate("contact", com.vaadin.flow.component.Component.class);

        Notification a = Notification.show("Message sent");
        System.out.println("A show(): elementText='" + a.getElement().getText()
                + "' prop='" + a.getElement().getProperty("text") + "'");

        Notification b = new Notification(new Span("Message sent"));
        b.open();
        System.out.println("B component: elementText='" + b.getElement().getText()
                + "' prop='" + b.getElement().getProperty("text") + "'");

        Notification c = new Notification();
        c.setText("Message sent");
        c.add(new Text("Message sent"));
        c.open();
        System.out.println("C both: elementText='" + c.getElement().getText()
                + "' prop='" + c.getElement().getProperty("text") + "'");

        Notification d = new Notification();
        d.setText("Message sent");
        d.getElement().appendChild(com.vaadin.flow.dom.Element.createText("Message sent"));
        d.open();
        System.out.println("D textnode: elementText='" + d.getElement().getText()
                + "' prop='" + d.getElement().getProperty("text") + "'");

        System.out.println("matches withTextContaining: "
                + $(Notification.class).withTextContaining("Message sent").all().size());
        System.out.println("total notifications: " + $(Notification.class).all().size());
        UI.getCurrent();
    }
}
