+package com.example.contact;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.Notification.Position;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.dom.Element;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+
+/**
+ * Simple contact form: the user fills in a name, an email and a message and
+ * gets a confirmation. Nothing is stored, "sending" only confirms to the user.
+ */
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout {
+
+    private static final String CONFIRMATION = "Message sent";
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+
+    public ContactView() {
+        // The view decides when a field is invalid, so the components must not
+        // reset that state on their own.
+        name.setManualValidation(true);
+        name.setErrorMessage("Name is required");
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(event -> {
+            if (!event.getValue().isBlank()) {
+                name.setInvalid(false);
+            }
+        });
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> sendMessage());
+
+        add(new H1("Contact"), name, email, message, send);
+    }
+
+    private void sendMessage() {
+        if (name.getValue() == null || name.getValue().isBlank()) {
+            name.setInvalid(true);
+            return;
+        }
+
+        name.setInvalid(false);
+        name.clear();
+        email.clear();
+        message.clear();
+
+        Notification notification = Notification.show(CONFIRMATION);
+        notification.setPosition(Position.MIDDLE);
+        // The card content lives in the "text" property, which is invisible to
+        // element text lookups. The extra (non-rendered) text node makes the
+        // confirmation readable both ways.
+        notification.getElement().appendChild(Element.createText(CONFIRMATION));
+    }
+
+}
